import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Glossary of Embedded Linux & Yocto Terms","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md"}'),d={name:"glossary.md"};function s(c,e,i,n,l,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary-of-embedded-linux-yocto-terms" tabindex="-1">Glossary of Embedded Linux &amp; Yocto Terms <a class="header-anchor" href="#glossary-of-embedded-linux-yocto-terms" aria-label="Permalink to &quot;Glossary of Embedded Linux &amp; Yocto Terms&quot;">​</a></h1><p>A comprehensive reference of all terminology used across the 16-Day Masterclass, sourced from official <a href="https://docs.yoctoproject.org/ref-manual/terms.html" target="_blank" rel="noreferrer">Yocto Project documentation</a>.</p><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><p><strong>Append File (<code>.bbappend</code>)</strong>: A file that extends or overrides an existing recipe without modifying the original. Must match the recipe name (e.g., <code>busybox_%.bbappend</code> extends any version of <code>busybox</code>). See <a href="/day16-filespath-splashscreen-and-bbappends.html">Day 16</a>.</p><p><strong>Autotools</strong>: The GNU build system (<code>autoconf</code>, <code>automake</code>, <code>libtool</code>) used by many open-source projects. In Yocto, use <code>inherit autotools</code> to automatically handle <code>./configure &amp;&amp; make &amp;&amp; make install</code>. See <a href="/day14-autotools-and-cmake-build-systems.html">Day 14</a>.</p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><p><strong><code>BB_NUMBER_THREADS</code></strong>: Configuration variable in <code>local.conf</code> controlling how many BitBake tasks execute in parallel. Typically set to the number of CPU cores.</p><p><strong>BitBake</strong>: The task execution engine at the heart of the Yocto build system. Written in Python, BitBake parses recipes, resolves dependency graphs, fetches source code, and orchestrates the entire build pipeline. See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><p><strong>Board Support Package (BSP)</strong>: A collection of metadata (machine configuration, kernel patches, bootloader recipes, device tree files) that enables Yocto to build images for a specific hardware platform. See <a href="/day4-yocto-releases-bsp-layers-wic.html">Day 4</a>.</p><p><strong>Bootloader</strong>: The first software executed after CPU power-on reset. Initializes critical hardware (clocks, DRAM) and loads the Linux kernel. Common bootloaders: U-Boot, Barebox. See <a href="/day3-beaglebone-black-hardware-bringup.html">Day 3</a>.</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><p><strong>Class (<code>.bbclass</code>)</strong>: A shared module of build logic that recipes can inherit using <code>inherit &lt;class&gt;</code>. Examples: <code>autotools</code>, <code>cmake</code>, <code>core-image</code>, <code>kernel</code>. See <a href="/day14-autotools-and-cmake-build-systems.html">Day 14</a>.</p><p><strong>CMake</strong>: A cross-platform build system generator. In Yocto, use <code>inherit cmake</code>. See <a href="/day14-autotools-and-cmake-build-systems.html">Day 14</a>, <a href="/day15-cmake-recipes-and-devshell-debugging.html">Day 15</a>.</p><p><strong>Cross-Compiler</strong>: A compiler that runs on one architecture (host, e.g., x86_64) but generates binaries for a different architecture (target, e.g., ARM). See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><p><strong><code>DEPENDS</code></strong>: Specifies build-time dependencies. Lists recipe names that must be built before the current recipe. Populates <code>recipe-sysroot</code> with headers and libraries. See <a href="/day13-recipe-dependencies-depends-rdepends.html">Day 13</a>.</p><p><strong><code>DESTDIR</code> / <code>${D}</code></strong>: The staging directory representing the target root filesystem. <code>do_install</code> copies files here, and <code>do_package</code> splits them into packages. See <a href="/day8-writing-recipes-and-c-apps.html">Day 8</a>.</p><p><strong>Device Tree Blob (<code>.dtb</code>)</strong>: A binary data structure describing hardware peripherals (memory-mapped registers, interrupt assignments, bus topology) to the Linux kernel. Compiled from Device Tree Source (<code>.dts</code>) files using <code>dtc</code>. See <a href="/day3-beaglebone-black-hardware-bringup.html">Day 3</a>.</p><p><strong>Devshell</strong>: An interactive development shell launched with <code>bitbake -c devshell &lt;recipe&gt;</code>. Provides a terminal with all cross-compilation environment variables pre-set. See <a href="/day15-cmake-recipes-and-devshell-debugging.html">Day 15</a>.</p><p><strong><code>DL_DIR</code></strong>: The directory where BitBake stores downloaded source archives and git repositories. Defaults to <code>build/downloads/</code>. Can be shared across builds.</p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><p><strong><code>EXTRA_IMAGE_FEATURES</code></strong>: Set in <code>conf/local.conf</code> to inject image features across all local builds without modifying image recipes. See <a href="/day7-custom-image-recipes-and-features.html">Day 7</a>.</p><p><strong><code>EXTRA_OECONF</code></strong>: Passes additional arguments to <code>./configure</code> when using <code>inherit autotools</code>. See <a href="/day14-autotools-and-cmake-build-systems.html">Day 14</a>.</p><p><strong><code>EXTRA_OECMAKE</code></strong>: Passes additional <code>-D</code> definitions to <code>cmake</code> when using <code>inherit cmake</code>. See <a href="/day14-autotools-and-cmake-build-systems.html">Day 14</a>.</p><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><p><strong><code>FILESEXTRAPATHS</code></strong>: Extends the search path for local files referenced in <code>SRC_URI</code>. Critical for <code>.bbappend</code> files. See <a href="/day16-filespath-splashscreen-and-bbappends.html">Day 16</a>.</p><p><strong><code>FILES:${PN}</code></strong>: Lists file patterns belonging to the main runtime package. Resolving <code>[installed-vs-shipped]</code> errors requires adding missing paths here. See <a href="/day11-package-splitting-and-installed-vs-shipped.html">Day 11</a>.</p><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><p><strong><code>IMAGE_FEATURES</code></strong>: A high-level variable enabling predefined feature sets in image recipes (e.g., <code>ssh-server-dropbear</code>, <code>debug-tweaks</code>, <code>read-only-rootfs</code>). See <a href="/day7-custom-image-recipes-and-features.html">Day 7</a>.</p><p><strong><code>IMAGE_INSTALL</code></strong>: Lists packages to include in the root filesystem image. Use <code>:append</code> syntax to add packages. See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><p><strong>Layer</strong>: A directory of related metadata (recipes, classes, configuration) that can be added to or removed from a build. Prefixed with <code>meta-</code> (e.g., <code>meta-raspberrypi</code>, <code>meta-ti</code>, <code>meta-xilinx</code>). See <a href="/day2-yocto-architecture-terminology-workflow.html">Day 2</a>.</p><p><strong><code>LIC_FILES_CHKSUM</code></strong>: A mandatory recipe variable containing the checksum of the software&#39;s license file. BitBake verifies this checksum to detect unintended license changes. See <a href="/day8-writing-recipes-and-c-apps.html">Day 8</a>.</p><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><p><strong><code>MACHINE</code></strong>: Defines the target hardware platform. Set in <code>conf/local.conf</code>. Examples: <code>qemuarm</code>, <code>beaglebone-yocto</code>, <code>raspberrypi3</code>, <code>zedboard-zynq7</code>. See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><p><strong>Metadata</strong>: The collective term for all configuration files (<code>.conf</code>), recipes (<code>.bb</code>), appends (<code>.bbappend</code>), and classes (<code>.bbclass</code>).</p><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><p><strong><code>oe_runmake</code></strong>: A Yocto helper function that executes <code>make</code> with cross-compilation variables automatically passed. See <a href="/day9-build-logs-debugging-makefiles.html">Day 9</a>.</p><p><strong>OpenEmbedded-Core (OE-Core)</strong>: The core metadata layer (<code>meta/</code>) containing fundamental recipes, classes, and configuration for building embedded Linux. See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><p><strong><code>PACKAGES</code></strong>: Variable listing all output packages generated by a recipe, in left-to-right priority order. See <a href="/day11-package-splitting-and-installed-vs-shipped.html">Day 11</a>.</p><p><strong><code>PARALLEL_MAKE</code></strong>: Sets the <code>-j</code> flag for <code>make</code> commands. Controls compilation parallelism within a single recipe.</p><p><strong>Poky</strong>: The Yocto Project reference distribution combining BitBake + OE-Core + meta-poky + meta-yocto-bsp. See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><p><strong><code>RDEPENDS</code></strong>: Specifies runtime dependencies. Lists package names that must be present on the target system. See <a href="/day13-recipe-dependencies-depends-rdepends.html">Day 13</a>.</p><p><strong>Recipe (<code>.bb</code>)</strong>: A file containing instructions for building a single software package. Defines where to fetch source code, how to compile it, and how to package the output. See <a href="/day8-writing-recipes-and-c-apps.html">Day 8</a>.</p><p><strong>Renode</strong>: An open-source hardware emulator supporting Zynq-7000/ZedBoard and other platforms. See <a href="/renode-emulation-guide.html">Renode Guide</a>.</p><p><strong>Root Filesystem (rootfs)</strong>: The complete directory hierarchy (<code>/bin</code>, <code>/etc</code>, <code>/lib</code>, <code>/usr</code>) that Linux mounts as <code>/</code> after booting. See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><p><strong>Shared State Cache (<code>sstate-cache</code>)</strong>: A directory storing compiled build artifacts keyed by input hash. Allows BitBake to skip rebuilding unchanged recipes, dramatically reducing build times. See <a href="/day2-yocto-architecture-terminology-workflow.html">Day 2</a>.</p><p><strong><code>SOLIBS</code> / <code>SOLIBSDEV</code></strong>: Variables controlling how versioned (<code>.so.1.0</code>) and unversioned (<code>.so</code>) shared libraries are assigned to packages. See <a href="/day12-static-and-dynamic-shared-libraries.html">Day 12</a>.</p><p><strong><code>SRC_URI</code></strong>: Specifies the location(s) of source code, patches, and local files for a recipe. Supports <code>http://</code>, <code>git://</code>, <code>file://</code>, and other fetcher protocols. See <a href="/day8-writing-recipes-and-c-apps.html">Day 8</a>.</p><p><strong><code>SRCREV</code></strong>: Specifies the exact Git commit hash to checkout. Ensures reproducible builds. See <a href="/day10-git-repositories-and-source-patching.html">Day 10</a>.</p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><p><strong>Toolchain</strong>: The cross-compiler, binutils, C library, and kernel headers used to compile software for the target architecture. See <a href="/day1-embedded-linux-yocto-foundations.html">Day 1</a>.</p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><p><strong>WIC (<code>.wic</code>)</strong>: A tool and disk image format that creates pre-partitioned, bootable SD card images. Configured via <code>.wks</code> (kickstart) files. See <a href="/day4-yocto-releases-bsp-layers-wic.html">Day 4</a>.</p><p><strong><code>WORKDIR</code></strong>: The temporary build directory for a recipe under <code>tmp/work/&lt;arch&gt;/&lt;pn&gt;/&lt;pv&gt;/</code>. Contains fetched sources, build outputs, and task logs. See <a href="/day8-writing-recipes-and-c-apps.html">Day 8</a>.</p>',59)])])}const g=o(d,[["render",s]]);export{m as __pageData,g as default};
